public class StringDeduplicationDemo {
    public static void main(String[] args) {
        // These two strings have distinct object identities and distinct backing arrays
        // initially, but G1 String Deduplication can merge their backing arrays post-GC.
        String s1 = new String("Enterprise Java Application Engine");
        String s2 = new String("Enterprise Java Application Engine");

        System.out.println("s1 == s2: " + (s1 == s2)); // false
        System.out.println("Backing arrays identical: " + (s1.getBytes() == s2.getBytes())); // false initially

        // Force GC with deduplication enabled to observe backing array merging
        System.gc();
    }
}
